<?php if ($canWrite): ?><details class="card form-card" <?= $editing ? 'open' : '' ?>><summary><?= $editing && $editing['id'] ? 'Modifier la fiche membre' : '+ Ajouter un membre' ?></summary><form method="post" action="members" class="form-grid"><input type="hidden" name="csrf" value="<?= e(csrf()) ?>"><input type="hidden" name="id" value="<?= e($editing['id'] ?? 0) ?>"><label>Prénom *<input name="first_name" maxlength="100" required value="<?= e($editing['first'] ?? '') ?>"></label><label>Nom *<input name="last_name" maxlength="100" required value="<?= e($editing['last'] ?? '') ?>"></label><label>Téléphone<input name="phone" maxlength="30" placeholder="+216" value="<?= e($editing['phone'] ?? '') ?>"></label><label>E-mail <?= empty($editing['id']) ? '*' : '' ?><input name="email" type="email" maxlength="190" value="<?= e($editing['email'] ?? '') ?>" <?= empty($editing['id']) ? 'required' : '' ?>></label><p class="form-hint"><?= !empty($editing['id']) ? 'Le numéro de carte ne peut pas être modifié.' : 'Le numéro de carte est attribué automatiquement à la création.' ?></p><label>Gouvernorat<select name="governorate"><option value="">Sélectionner</option><?php foreach (['Ariana','Béja','Ben Arous','Bizerte','Gabès','Gafsa','Jendouba','Kairouan','Kasserine','Kébili','Kef','Mahdia','Manouba','Médenine','Monastir','Nabeul','Sfax','Sidi Bouzid','Siliana','Sousse','Tataouine','Tozeur','Tunis','Zaghouan'] as $g): ?><option <?= ($editing['governorate'] ?? '') === $g ? 'selected' : '' ?>><?= e($g) ?></option><?php endforeach; ?></select></label><label>Date de naissance<input type="date" name="birth_date" value="<?= e($editing['birth'] ?? '') ?>"></label><label>Statut<select name="status"><?php foreach (['active'=>'Actif','inactive'=>'Inactif','blacklisted'=>'Liste noire'] as $key=>$label): ?><option value="<?= e($key) ?>" <?= ($editing['status'] ?? 'active') === $key ? 'selected' : '' ?>><?= e($label) ?></option><?php endforeach; ?></select></label><div class="form-actions"><button class="primary">Enregistrer</button><?php if ($editing): ?><a href="members">Annuler</a><?php endif; ?></div></form></details><?php endif; ?>
<section class="card management-table"><div class="card-head"><div><h3>Votre communauté</h3><p><?= $total ?> membre(s) enregistré(s)</p></div></div><form action="members" class="search-form" method="get"><input name="q" placeholder="Nom, téléphone ou carte…" value="<?= e($q) ?>"><button class="primary">Rechercher</button><?php if ($q): ?><a href="members">Effacer</a><?php endif; ?></form><?php if (($_SESSION['user']['role'] ?? '')==='Admin' && $members): ?><form id="bulk-member-removal" method="post" action="removals?type=members&amp;from=members" class="removal-confirm" onsubmit="return confirm('Traiter les membres sélectionnés ? Les suppressions définitives sont irréversibles ; les historiques liés seront conservés.');"><input type="hidden" name="csrf" value="<?= e(csrf()) ?>"><label for="bulk-admin-password">Mot de passe administrateur</label><input id="bulk-admin-password" type="password" name="admin_password" autocomplete="current-password" required maxlength="1024"><label><input type="checkbox" name="confirm" value="1" required> Je confirme la sélection et ses conséquences</label><button type="submit" class="primary">Supprimer la sélection</button></form><p class="form-hint">Sélection limitée à la page affichée. Les membres ayant un historique sont désactivés ; leurs abonnements et réservations restent inchangés.</p><?php endif; ?><div class="table-scroll"><table><thead><tr><?php if (($_SESSION['user']['role'] ?? '')==='Admin'): ?><th><input type="checkbox" id="select-members" aria-label="Sélectionner les membres de cette page"></th><?php endif; ?><th>MEMBRE</th><th>CARTE</th><th>GOUVERNORAT</th><th>STATUT</th><th>ACTION</th></tr></thead><tbody><?php foreach ($members as $m): ?><tr><?php if (($_SESSION['user']['role'] ?? '')==='Admin'): ?><td><input type="checkbox" name="ids[]" value="<?= (int)$m['id'] ?>" form="bulk-member-removal" class="member-selection" aria-label="Sélectionner <?= e($m['first_name'].' '.$m['last_name']) ?>"><input type="hidden" name="versions[<?= (int)$m['id'] ?>]" value="<?= e($removalVersions[(int)$m['id']]) ?>" form="bulk-member-removal"></td><?php endif; ?><td><div class="member"><div class="avatar <?= e($m['avatar_color']) ?>"><?= e(mb_substr($m['first_name'],0,1).mb_substr($m['last_name'],0,1)) ?></div><div><strong><?= e($m['first_name'].' '.$m['last_name']) ?></strong><small><?= e($m['phone'] ?: '—') ?></small></div></div></td><td><?= e($m['card_number'] ?: '—') ?></td><td><?= e($m['governorate'] ?: '—') ?></td><td><span class="status <?= $m['status'] !== 'active' ? 'expired' : '' ?>"><?= e(['active'=>'Actif','inactive'=>'Inactif','blacklisted'=>'Liste noire'][$m['status']]) ?></span></td><td><a class="text-link" href="member_profile?id=<?= (int)$m['id'] ?>">Voir la fiche</a><?php if ($canWrite): ?> · <a class="text-link" href="members?edit=<?= (int)$m['id'] ?>">Modifier</a> · <a class="text-link" href="member_card?id=<?= (int)$m['id'] ?>">Carte QR</a><?php endif; ?></td></tr><?php endforeach; ?><?php if (!$members): ?><tr><td colspan="<?= ($_SESSION['user']['role'] ?? '')==='Admin' ? 6 : 5 ?>" class="empty">Aucun membre trouvé.</td></tr><?php endif; ?></tbody></table></div><div class="pagination"><?php if ($pageNumber>1): ?><a href="members?q=<?= urlencode($q) ?>&amp;p=<?= $pageNumber-1 ?>">← Précédent</a><?php endif; ?><span>Page <?= $pageNumber ?> / <?= max(1,(int)ceil($total/10)) ?></span><?php if ($pageNumber*10<$total): ?><a href="members?q=<?= urlencode($q) ?>&amp;p=<?= $pageNumber+1 ?>">Suivant →</a><?php endif; ?></div></section>
